oxy_webhelp_navlinks = {"tocId-d39307e43674":{"topics":[{"title":"Atlassian Confluence backups","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> backs up Atlassian Confluence data by taking snapshots of the         spaces in your Atlassian site, automatically according to an SLA Domain or on         demand.<\/p>","href":"confluence\/confluence_backups.html","attributes":{"data-id":"confluence_backups"},"menu":{"hasChildren":false},"tocID":"confluence_backups-d39307e43675","next":"confluence_backups-d39307e43675"},{"title":"Removing an Atlassian site","shortdesc":"<p class=\"shortdesc\">Remove an Atlassian site from <span class=\"ph\">RSC<\/span> to stop protecting it and delete         its snapshots and configuration.<\/p>","href":"confluence\/confluence_deleting_site.html","attributes":{"data-id":"confluence_deleting_site"},"menu":{"hasChildren":false},"tocID":"confluence_deleting_site-d39307e43699","topics":[]},{"title":"Managing protection for SaaS applications","shortdesc":"<p class=\"shortdesc\">Protect SaaS applications, such as Atlassian Jira and Salesforce, by assigning them         to an SLA Domain. This protects the instance by applying backup frequency and retention         policies.<\/p>","href":"common\/saas_managing_protection.html","attributes":{"data-id":"saas_managing_protection"},"menu":{"hasChildren":false},"tocID":"saas_managing_protection-d39307e43713","topics":[]},{"title":"Deleting an SLA Domain for SaaS applications","shortdesc":"<p class=\"shortdesc\">Delete an SLA Domain you created for SaaS applications from <span class=\"ph\">RSC<\/span> when         it is no longer needed.<\/p>","href":"common\/saas_deleting_sla_domain.html","attributes":{"data-id":"saas_deleting_sla_domain"},"menu":{"hasChildren":false},"tocID":"saas_deleting_sla_domain-d39307e43724","topics":[]}]}};